package opsagent

import (
	"encoding/binary"
	"math"
	"time"
)

type Sample struct {
	Metric string
	Labels map[string]string
	Value  float64
	At     time.Time
}

func samplesToWriteRequest(samples []Sample) []byte {
	var out []byte
	for i := range samples {
		out = appendTagBytes(out, 1, marshalTimeSeries(samples[i]))
	}
	return out
}

func marshalTimeSeries(s Sample) []byte {
	var msg []byte
	msg = appendTagBytes(msg, 1, marshalLabel("__name__", s.Metric))
	for k, v := range s.Labels {
		msg = appendTagBytes(msg, 1, marshalLabel(k, v))
	}
	ts := s.At
	if ts.IsZero() {
		ts = time.Now().UTC()
	}
	msg = appendTagBytes(msg, 2, marshalSample(s.Value, ts.UnixMilli()))
	return msg
}

func marshalLabel(name, value string) []byte {
	var msg []byte
	msg = appendTagBytes(msg, 1, []byte(name))
	msg = appendTagBytes(msg, 2, []byte(value))
	return msg
}

func marshalSample(value float64, timestampMs int64) []byte {
	var msg []byte
	msg = append(msg, byte((1<<3)|1)) // field 1, wire type 1 (64-bit)
	var buf [8]byte
	binary.LittleEndian.PutUint64(buf[:], math.Float64bits(value))
	msg = append(msg, buf[:]...)
	msg = appendVarint(msg, (2<<3)|0) // field 2, wire type 0
	msg = appendVarint(msg, uint64(timestampMs))
	return msg
}

func appendTagBytes(dst []byte, field int, payload []byte) []byte {
	dst = appendVarint(dst, uint64((field<<3)|2))
	dst = appendVarint(dst, uint64(len(payload)))
	return append(dst, payload...)
}

func appendVarint(dst []byte, v uint64) []byte {
	for v >= 0x80 {
		dst = append(dst, byte(v)|0x80)
		v >>= 7
	}
	return append(dst, byte(v))
}

package opsagent

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/golang/snappy"
)

type RemoteConfig struct {
	URL   string
	User  string
	Token string
}

func RemoteConfigFromEnv() (RemoteConfig, bool) {
	url := strings.TrimSpace(os.Getenv("GRAFANA_CLOUD_PROMETHEUS_URL"))
	user := strings.TrimSpace(os.Getenv("GRAFANA_CLOUD_PROMETHEUS_USER"))
	token := strings.TrimSpace(os.Getenv("GRAFANA_CLOUD_API_TOKEN"))
	if url == "" || user == "" || token == "" {
		return RemoteConfig{}, false
	}
	return RemoteConfig{URL: url, User: user, Token: token}, true
}

func RemoteWrite(ctx context.Context, cfg RemoteConfig, samples []Sample) error {
	if len(samples) == 0 {
		return nil
	}
	compressed := snappy.Encode(nil, samplesToWriteRequest(samples))
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, cfg.URL, bytes.NewReader(compressed))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Encoding", "snappy")
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("X-Prometheus-Remote-Write-Version", "0.1.0")
	req.SetBasicAuth(cfg.User, cfg.Token)
	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode/100 != 2 {
		slurp, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return fmt.Errorf("remote_write status=%d body=%s", resp.StatusCode, strings.TrimSpace(string(slurp)))
	}
	return nil
}

package opsagent

import (
	"context"
	"flag"
	"log"
	"os"
	"strconv"
	"strings"
	"time"
)

func Main() {
	once := flag.Bool("once", false, "collect one interval and exit")
	flag.Parse()

	interval := envDuration("OPS_METRICS_INTERVAL", time.Minute)
	procRoot := envString("OPS_PROC_ROOT", "/host/proc")
	hostRoot := envString("OPS_HOST_ROOT", "/host/root")
	healthURL := envString("OPS_HEALTH_URL", "http://127.0.0.1:10000/api/health")
	instance := envString("OPS_INSTANCE", "kuchup-ec2")
	dockerSocket := envString("OPS_DOCKER_SOCKET", "/var/run/docker.sock")
	names := defaultContainerNames()
	if raw := strings.TrimSpace(os.Getenv("OPS_CONTAINER_NAMES")); raw != "" {
		names = nil
		for _, part := range strings.Split(raw, ",") {
			part = strings.TrimSpace(part)
			if part != "" {
				names = append(names, part)
			}
		}
	}

	ctx := context.Background()
	var store *Store
	if strings.TrimSpace(os.Getenv("DATABASE_URL")) != "" {
		var err error
		store, err = OpenStore(ctx)
		if err != nil {
			log.Fatalf("postgres: %v", err)
		}
		defer store.Close(ctx)
	}
	remote, remoteOK := RemoteConfigFromEnv()
	if !remoteOK {
		log.Print("Grafana Cloud remote_write disabled — set GRAFANA_CLOUD_PROMETHEUS_URL, GRAFANA_CLOUD_PROMETHEUS_USER, GRAFANA_CLOUD_API_TOKEN")
	}

	collect := func() {
		now := time.Now().UTC()
		var batch []Sample
		host, err := hostSamples(procRoot, hostRoot, instance)
		if err != nil {
			log.Printf("host metrics: %v", err)
		} else {
			batch = append(batch, host...)
		}
		docker, err := dockerSamples(ctx, dockerSocket, names, instance)
		if err != nil {
			log.Printf("docker metrics: %v", err)
		} else {
			batch = append(batch, docker...)
		}
		batch = append(batch, probeSample(ctx, healthURL, instance))
		for i := range batch {
			batch[i].At = now
		}
		if store != nil {
			if err := store.InsertSamples(ctx, batch); err != nil {
				log.Printf("postgres insert: %v", err)
			}
		}
		if remoteOK {
			if err := RemoteWrite(ctx, remote, batch); err != nil {
				log.Printf("remote_write: %v", err)
			}
		}
		log.Printf("collected samples=%d", len(batch))
	}

	collect()
	if *once {
		return
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for range ticker.C {
		collect()
	}
}

func envString(key, fallback string) string {
	v := strings.TrimSpace(os.Getenv(key))
	if v == "" {
		return fallback
	}
	return v
}

func envDuration(key string, fallback time.Duration) time.Duration {
	raw := strings.TrimSpace(os.Getenv(key))
	if raw == "" {
		return fallback
	}
	if d, err := time.ParseDuration(raw); err == nil {
		return d
	}
	if sec, err := strconv.Atoi(raw); err == nil && sec > 0 {
		return time.Duration(sec) * time.Second
	}
	return fallback
}

package opsagent

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"strings"
	"time"
)

type dockerStats struct {
	MemoryStats struct {
		Usage uint64 `json:"usage"`
	} `json:"memory_stats"`
	CPUStats struct {
		CPUUsage struct {
			TotalUsage uint64 `json:"total_usage"`
		} `json:"cpu_usage"`
	} `json:"cpu_stats"`
}

func dockerSamples(ctx context.Context, socket string, names []string, instance string) ([]Sample, error) {
	if strings.TrimSpace(socket) == "" {
		socket = "/var/run/docker.sock"
	}
	client := &http.Client{
		Transport: &http.Transport{
			DialContext: func(_ context.Context, _, _ string) (net.Conn, error) {
				return net.Dial("unix", socket)
			},
		},
		Timeout: 15 * time.Second,
	}
	byName, err := dockerRunningIDs(ctx, client)
	if err != nil {
		return nil, err
	}
	var out []Sample
	for _, want := range names {
		want = strings.TrimPrefix(strings.TrimSpace(want), "/")
		if want == "" {
			continue
		}
		id, ok := byName[want]
		if !ok {
			continue
		}
		stats, err := dockerOneShotStats(ctx, client, id)
		if err != nil {
			continue
		}
		labels := map[string]string{
			"name":     want,
			"instance": instance,
			"job":      "integrations/cadvisor",
		}
		out = append(out,
			Sample{Metric: "container_memory_usage_bytes", Labels: copyLabels(labels), Value: float64(stats.MemoryStats.Usage)},
			Sample{Metric: "container_cpu_usage_seconds_total", Labels: copyLabels(labels), Value: float64(stats.CPUStats.CPUUsage.TotalUsage) / 1e9},
		)
	}
	return out, nil
}

type dockerContainer struct {
	ID    string   `json:"Id"`
	Names []string `json:"Names"`
}

func dockerRunningIDs(ctx context.Context, client *http.Client) (map[string]string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://docker/v1.44/containers/json", nil)
	if err != nil {
		return nil, err
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("containers/json: %s", strings.TrimSpace(string(body)))
	}
	var list []dockerContainer
	if err := json.NewDecoder(resp.Body).Decode(&list); err != nil {
		return nil, err
	}
	out := make(map[string]string, len(list))
	for _, c := range list {
		for _, n := range c.Names {
			out[strings.TrimPrefix(n, "/")] = c.ID
		}
	}
	return out, nil
}

func dockerOneShotStats(ctx context.Context, client *http.Client, id string) (*dockerStats, error) {
	url := fmt.Sprintf("http://docker/v1.44/containers/%s/stats?stream=false", id)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("stats: %s", strings.TrimSpace(string(body)))
	}
	var stats dockerStats
	if err := json.NewDecoder(resp.Body).Decode(&stats); err != nil {
		return nil, err
	}
	return &stats, nil
}

func defaultContainerNames() []string {
	return []string{
		"relocation-panel",
		"relocation-fetch-worker",
		"relocation-fetch-merge",
		"relocation-mcp",
		"relocation-caddy",
		"relocation-role-propagator",
		"relocation-playwright-worker",
		"relocation-ops-agent",
		"relocation-redis",
		"pg",
	}
}

