func TestDashboardMetricNames(t *testing.T) {
	want := map[string]bool{
		"node_memory_MemAvailable_bytes":    true,
		"node_filesystem_avail_bytes":       true,
		"node_filesystem_size_bytes":        true,
		"node_load1":                        true,
