		"node_load1",
		"container_memory_usage_bytes",
		"container_cpu_usage_seconds_total",
		"probe_success",
	}
	for _, name := range got {
		if !want[name] {
			t.Fatalf("unexpected dashboard metric %q", name)
		}
		delete(want, name)
	}
